SELECT kv.id, kv.document_id AS documentId, kv.chunk_index AS chunkIndex, kv.content, kv.metadata, CAST(NULL AS double precision) AS score FROM knowledge_vectors kv WHERE kv.user_id = #{userId} AND kv.knowledge_id = #{knowledgeId} AND kv.document_id IN
#{did}
ORDER BY kv.document_id, kv.chunk_index NULLS LAST
